 11	{
 12		public override bool TryTrigs(int trig, Vector2 location, float rotation, int face, Vector2 straj, Character c, Part part, bool continuous, MonsterDef mDef, Vector2 scaling, bool flip, int lastFlame)
 13		{
 14			switch (trig)
 15			{
 16			case 38:
 17				if (c.state == 0)
 18				{
 19					ParticleManager.AddNormalParticle(2, location, Rand.GetRandomVec2(-50f, 50f, -50f, 50f), Rand.GetRandomFloat(0.25f, 0.35f), 0f, 0, c.ID);
 20					c.stats.PlayStep();
 21				}
 22				break;
 23			case 61:
 24				Sound.Play3DSound("crash", location, 0);
 25				ParticleManager.AddNormalParticle(33, location, new Vector2(((float)c.face - 0.5f) * -3200f, 0f), 0.125f, 0f, -1, c.ID);
 26				break;
 27			case 62:
 28				Sound.Play3DSound("crash", location, 0);
 29				ParticleManager.AddNormalParticle(34, location, new Vector2(((float)c.face - 0.5f) * -3200f, 0f), 0.125f, 0f, -1, c.ID);
 30				break;
 31			case 58:
 32			{
 33				Sound.Play3DSound("crash", location, 0);
 34				for (int i = 0; i < 5; i++)
 35				{
 36					ParticleManager.AddNormalParticle(20, location, Rand.GetRandomVec2(-10f, 10f, -500f, 0f), Rand.GetRandomFloat(1f, 2f), 0f, -1, c.ID);
 37				}
 38				ParticleManager.AddNormalParticle(30, location, new Vector2(((float)c.face - 0.5f) * 1600f, 0f), 0.125f, 0f, -1, c.ID);
 39				break;
 40			}
 41			case 59:
 42			{
 43				Sound.Play3DSound("crashbig", location, 0);
 44				for (int j = 0; j < 5; j++)
 45				{
 46					ParticleManager.AddNormalParticle(20, location, Rand.GetRandomVec2(-10f, 10f, -500f, 0f), Rand.GetRandomFloat(1f, 2f), 0f, -1, -1);
 47				}
 48				ParticleManager.AddNormalParticle(30, location, new Vector2(((float)c.face - 0.5f) * 1600f, 0f), 0.25f, 0f, -1, c.ID);
 49				break;
 50			}
 51			case 11:
 52				if (c.state == 0)
 53				{
 54					ParticleManager.AddNormalParticle(2, location, Rand.GetRandomVec2(-50f, 50f, -50f, 50f), Rand.GetRandomFloat(0.5f, 1f), 0f, 0, c.ID);
 55				}
 56				break;
 57			case 14:
 58				if (GameStateManager.wordsFrame < 2f)
 59				{
 60					c.trigs.effects.MakeStep(c, location);
 61				}
 62				break;
 63			default:
 64				return false;
 65			}
 66			return true;
 67		}
