 77	public class CharTrigGore : CharTrigActivator
 78	{
 79		public override bool TryTrigs(int trig, Vector2 location, float rotation, int face, Vector2 straj, Character c, Part part, bool continuous, MonsterDef mDef, Vector2 scaling, bool flip, int lastFlame)
 80		{
 81			switch (trig)
 82			{
 83			case 240:
 84				if (c.grabbingExe > -1)
 85				{
 86					Character other = CharMgr.character[c.grabbingExe];
 87					HitGore.MakeBloodsplosion(location, c, other);
 88				}
 89				else
 90				{
 91					HitGore.MakeBloodsplosion(location, null, c);
 92				}
 93				break;
 94			case 161:
 95				if (c.grabbingExe > -1)
 96				{
 97					Character character = CharMgr.character[c.grabbingExe];
 98					character.anim.SetAnimation("stomped");
 99					if (c.playerIdx > -1)
100					{
101						c.GetPlayer().hitVibration = 1f;
102					}
103					HitGore.MakeBloodsplosion(location, c, character);
104					c.grabbingExe = -1;
105					character.grabbedByExe = -1;
106					character.hp = 0f;
107				}
108				break;
109			case 6:
110			case 244:
111			{
112				int creature = MonsterCatalog.catalog[c.monsterIdx].creature;
113				if (c.grabbedBy > -1)
114				{
115					creature = MonsterCatalog.catalog[CharMgr.character[c.grabbedBy].monsterIdx].creature;
116				}
117				if (!(c.anim.GetGore() < 5f) || ((uint)creature > 5u && creature != 9))
118				{
119					break;
120				}
121				int type = 4;
122				int type2 = 13;
123				int type3 = 6;
124				int num = 146;
125				switch (creature)
126				{
127				case 3:
128					type = 84;
129					type2 = 85;
130					type3 = 87;
131					num = 147;
132					break;
133				case 4:
134					type = 88;
135					type2 = 89;
136					type3 = 90;
137					num = -1;
138					break;
139				}
140				straj *= new Vector2(1f, -1f);
141				if (trig == 244)
142				{
143					straj = Rand.GetRandomVec2(-1f, 1f, -10f, 0f);
144				}
145				float num2 = 1f;
146				if (Rand.CoinToss(0.5f))
147				{
148					ParticleManager.AddSubtractiveParticle(type, location, straj * Rand.GetRandomFloat(1f, 50f) + Rand.GetRandomVec2(-50f, 50f, -50f, 50f), Rand.GetRandomFloat(0.5f, 1f) * num2, 0f, 0, c.ID);
149				}
150				else
151				{
152					ParticleManager.AddNormalParticle(type2, location, straj * Rand.GetRandomFloat(1f, 50f) + Rand.GetRandomVec2(-50f, 50f, -50f, 50f), Rand.GetRandomFloat(0.5f, 1f) * num2, 0f, 0, c.ID);
153				}
154				if (num > -1 && Rand.CoinToss(0.5f))
155				{
156					int num3 = ParticleManager.AddSubtractiveParticle(num, location + straj, straj * Rand.GetRandomFloat(1f, 50f) + Rand.GetRandomVec2(-150f, 150f, -50f, 50f), Rand.GetRandomFloat(0.2f, 0.4f) * num2, 0f, 0, c.ID);
157					if (num3 > -1)
158					{
159						ParticleManager.particleList[3].particle[num3].aux = 1;
160					}
161					ParticleManager.AddBackRefractParticle(148, location + straj, straj * Rand.GetRandomFloat(1f, 50f) + Rand.GetRandomVec2(-150f, 150f, -50f, 50f), Rand.GetRandomFloat(0.2f, 0.4f) * num2, 0f, 0, c.ID);
162				}
163				else
164				{
165					int num4 = ParticleManager.AddSubtractiveParticle(type3, location, straj * Rand.GetRandomFloat(1f, 50f) + Rand.GetRandomVec2(-50f, 50f, -50f, 50f), Rand.GetRandomFloat(0.5f, 1f) * num2, 0f, 0, c.ID);
166					if (num4 > -1 && Rand.CoinToss(0.2f))
167					{
168						ParticleManager.particleList[3].particle[num4].aux = 1;
169					}
170				}
171				break;
172			}
173			default:
174				return false;
175			}
176			return true;
177		}
178	}
