337	public class CharTrigTraps : CharTrigActivator
338	{
339		public override bool TryTrigs(int trig, Vector2 location, float rotation, int face, Vector2 straj, Character c, Part part, bool continuous, MonsterDef mDef, Vector2 scaling, bool flip, int lastFlame)
340		{
341			if ((uint)(trig - 105) > 1u)
342			{
343				if (trig != 177)
344				{
345					return false;
346				}
347				ParticleManager.AddNormalParticle(142, location, new Vector2((c.face == 1) ? 1f : (-1f), 1f) * new Vector2(300f, -10f), 0f, rotation, c.face, c.ID);
348			}
349			else
350			{
351				Sound.PlaySpre((trig == 105) ? 16 : 17, location, 0);
352				if (c.update.hitSwipeFrame > 0.5f)
353				{
354					c.update.hitSwipeFrame = 0f;
355					c.update.hitSwipeCount = 0;
356				}
357				Vector2 vector = straj * Rand.GetRandomVec2(0.9f, 1.1f, -1.1f, -0.9f) * 50f;
358				if (trig == 105)
359				{
360					vector *= 0.1f;
361				}
362				else
363				{
364					vector.Y += Rand.GetRandomFloat(-1f, 1f) * 50f;
365					vector.X *= Rand.GetRandomFloat(1f, 1.4f);
366				}
367				int num = ParticleManager.AddAdditiveParticle(100, location, vector, 1f, 0f, -1, (trig == 105) ? (-1) : c.ID);
368				for (int i = 0; i < 3; i++)
369				{
370					Vector2 vector2 = vector + Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * new Vector2(400f, 400f);
371					ParticleManager.AddBackAdditiveParticle(80, location, vector2, Rand.GetRandomFloat(0f, 1f), Trig.GetAngle(default, vector2), -1, c.ID);
372				}
373				if (num > -1)
374				{
375					if (lastFlame > -1 && trig == 106)
376					{
377						ParticleManager.particleList[5].particle[num].aux = lastFlame;
378					}
379					else
380					{
381						ParticleManager.particleList[5].particle[num].aux = -1;
382					}
383				}
384				lastFlame = ((trig != 105) ? num : (-1));
385				c.trigs.lastFlame = lastFlame;
386			}
387			return true;
388		}
389	}

