		case "swoop":
			vector = c.traj;
			break;
		case "sleep":
		case "pickup":
			vector = default;
			break;
		case "hoverflame":
			vector = new Vector2(((float)c.face - 0.5f) * 1500f, 0f);
			break;
		case "hover":
		case "idle":
			if ((hoverTarg - c.loc).LengthSquared() > 100f)
			{
				Vector2 vector2 = hoverTarg - c.loc;
				float num5 = vector2.Length();
				Vector2 vector3 = vector2;
				vector3.Normalize();
				if (c.hoverSpeed < num2)
				{
					c.hoverSpeed += frameTime * num3;
				}
				if (c.hoverSpeed > num2)
				{
					c.hoverSpeed = num2;
				}
				if (num5 < 100f && c.hoverSpeed > num5 * 5f)
				{
					c.hoverSpeed = num5 * 5f;
				}
				vector = vector3 * c.hoverSpeed;
			}
			switch (MonsterCatalog.catalog[c.monsterIdx].ai)
			{
			case 31:
				vector.Y += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 20f) * 200f;
				vector.X += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 8f) * 50f;
				break;
			case 12:
			case 30:
				vector.Y += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 10f) * 400f;
				vector.X += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 8f) * 200f;
				break;
			case 28:
				vector.Y += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 2f) * 40f;
				vector.X += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 1.5f) * 20f;
				break;
			case 20:
				vector.Y += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 2f) * 20f;
				vector.X += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 1.6f) * 10f;
				break;
			case 27:
				vector.X += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 2f) * 200f;
				vector.Y += (float)Math.Cos((MapMgr.map.delta + (float)c.ID) * 1.6f) * 10f;
				break;
			}
			break;
		case "gibbed":
		case "die":
			vector.Y = 100f;
			break;
		}
		if (!c.hoverSlide)
		{
			Vector2 traj = c.traj;
			c.traj += (vector - c.traj) * frameTime * num;
			if ((traj.X < vector.X && c.traj.X > vector.X) || (traj.X > vector.X && c.traj.X < vector.X))
			{
				c.traj.X = vector.X;
			}
			if ((traj.Y < vector.Y && c.traj.Y > vector.Y) || (traj.Y > vector.Y && c.traj.Y < vector.Y))
			{
				c.traj.Y = vector.Y;
			}
		}
		c.loc += c.traj * frameTime;
		float num6 = c.traj.X;
		switch (c.anim.animName)
		{
		case "die":
			if (MonsterCatalog.catalog[c.monsterIdx].ai == 13 && CharCols.TestCol(c.loc, falling: true, 0f))
			{
				c.loc.Y = CharCols.GetGround(c.loc);
				c.state = 0;
			}
			break;
		case "hover":
			if (c.charAI.attackType == 24 && c.loc.X > c.charAI.hoverTarg.X - 50f && c.loc.X < c.charAI.hoverTarg.X + 50f)
			{
				num6 = 0f;
			}
			break;
		default:
			num6 = 0f;
			break;
		case "idle":
			break;
		}
		if (PlayerMgr.GetMainPlayer().camMgr.latestArenaIdx > -1 && c.monsterIdx != 76 && c.playerIdx == -1 && !c.boss)
		{
			int activeArenaIdx = MapMgr.map.triggerMgr.GetActiveArenaIdx(c);
			Vector2 loc = c.loc;
			c.loc = pLoc;
			int activeArenaIdx2 = MapMgr.map.triggerMgr.GetActiveArenaIdx(c);
			c.loc = loc;
			if (activeArenaIdx > -1 && activeArenaIdx2 == -1)
			{
				c.loc = pLoc;
			}
		}
		if (c.hoverSlide)
		{
			return;
		}
		if (c.hoverAngle > num6)
		{
			c.hoverAngle -= frameTime * 2000f;
			if (c.hoverAngle < num6)
			{
				c.hoverAngle = num6;
			}
		}
		if (c.hoverAngle < num6)
		{
			c.hoverAngle += frameTime * 2000f;
			if (c.hoverAngle > num6)
			{
				c.hoverAngle = num6;
			}
		}
	}

