	public void CheckFalloff(Vector2 pLoc)
	{
		int groundCol = CharCols.GetGroundCol(c);
		MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
		float num = 30f;
		if (c.buffs.GetUpsideDown())
		{
			num = 0f - num;
		}
		if (c.platform > -1)
		{
			MapMgr.entityMgr.platform[c.platform].UpdateCharacter(c, pLoc, MapMgr.GetMap(), drawOnly: false);
			if (c.platform == -1 && !CharCols.TestCol(c.loc + new Vector2(-20f, num), falling: true, 0f) && !CharCols.TestCol(c.loc + new Vector2(20f, num), falling: true, 0f))
			{
				c.state = 1;
				c.traj.Y = -10f;
				c.anim.SetAnimation("fly");
				c.update.dropFrame = 0.25f;
				if (c.traj.X < 0f && c.traj.X > -200f)
				{
					c.traj.X = -200f;
				}
				if (c.traj.X > 0f && c.traj.X < 200f)
				{
					c.traj.X = 200f;
				}
			}
			return;
		}
		switch (groundCol)
		{
		case 2:
		case 3:
		case 6:
		case 7:
			c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
			return;
		case 8:
		case 9:
			c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
			return;
		}
		if (c.platform == -1)
		{
			int num2 = MapMgr.entityMgr.CheckPlatform(c, c.loc + new Vector2(0f, -1f), c.loc);
			if (num2 > -1)
			{
				c.platform = num2;
				return;
			}
		}
		if (!CharCols.TestCol(c.loc + new Vector2(-20f, num), falling: true, 0f) && !CharCols.TestCol(c.loc + new Vector2(20f, num), falling: true, 0f))
		{
			if ((monsterDef.GetRun(c) && monsterDef.ai != 2) || c.anim.animName == "hit" || c.anim.animName == "lroll" || c.anim.animName == "roll" || c.anim.animName == "froll" || c.anim.animName ==
			{
				c.state = 1;
				c.traj.Y = -10f;
				switch (c.anim.animName)
				{
				case "lroll":
				case "roll":
				case "mroll":
				case "froll":
					if (c.traj.X > 500f)
					{
						c.traj.X = 500f;
					}
					if (c.traj.X < -500f)
					{
						c.traj.X = -500f;
					}
					break;
				case "hit":
					c.anim.SetAnimation("fhit");
					break;
				default:
					c.anim.SetAnimation("fly");
					break;
				}
				if (c.traj.X < 0f && c.traj.X > -200f)
				{
					c.traj.X = -200f;
				}
				if (c.traj.X > 0f && c.traj.X < 200f)
				{
					c.traj.X = 200f;
				}
			}
			else
			{
				c.loc = pLoc;
			}
		}
		if (c.state == 0 && (!CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f) || !CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f)) && (!monsterDef.GetRun(c) 
		{
			if (monsterDef.ai == 2)
			{
				c.charAI.attackType = 0;
				c.charAI.attackFrame = -0.5f;
			}
			if (!CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f))
			{
				if (c.traj.X < 100f)
				{
					c.traj.X = 100f;
				}
				if (CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f))
				{
					float num3 = (float)(int)((c.loc.X + 30f) / 64f) * 64f + 20f;
					if (c.loc.X < num3)
					{
						c.loc.X = num3;
					}
				}
			}
			if (!CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f))
			{
				if (c.traj.X > -100f)
				{
					c.traj.X = -100f;
				}
				if (CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f))
				{
					float num4 = (float)((int)((c.loc.X - 30f) / 64f) + 1) * 64f - 20f;
					if (c.loc.X > num4)
					{
						c.loc.X = num4;
					}
				}
			}
		}
		if (c.state != 0)
		{
			return;
		}
		groundCol = CharCols.GetCol(c.loc + new Vector2(0f, 4f));
		if ((uint)(groundCol - 90) <= 7u)
		{
			bool flag = false;
			switch (groundCol)
			{
			case 90:
				flag = BlinkPlatMgr.mainBlinkPhase[0] == 0;
				break;
			case 91:
				flag = BlinkPlatMgr.mainBlinkPhase[1] == 0;
				break;
			case 92:
				flag = BlinkPlatMgr.quickBlinkPhase[0] == 0;
				break;
			case 93:
				flag = BlinkPlatMgr.quickBlinkPhase[1] == 0;
				break;
			case 94:
				flag = BlinkPlatMgr.quickBlinkPhase[2] == 0;
				break;
			case 95:
				flag = BlinkPlatMgr.quickBlinkPhase[3] == 0;
				break;
			case 96:
				flag = BlinkPlatMgr.quickBlinkPhase[4] == 0;
				break;
			case 97:
				flag = BlinkPlatMgr.quickBlinkPhase[5] == 0;
				break;
			}
			if (flag)
			{
				c.traj.Y = 0f;
				c.state = 1;
				c.anim.SetAnimation("fly");
			}
		}
	}

	public void ApplyFriction()
	{
		if (c.traj.X > 0f)
		{
			c.traj.X -= Game1.frameTime * 1500f;
			if (c.traj.X < 0f)
			{
				c.traj.X = 0f;
			}
		}
		if (c.traj.X < 0f)
		{
			c.traj.X += Game1.frameTime * 1500f;
			if (c.traj.X > 0f)
			{
				c.traj.X = 0f;
			}
		}
	}
}

public class CharUpdateDeath
{
	private Character c;

	public CharUpdateDeath(Character c)
	{
		this.c = c;
	}

	public void KillMe()
	{
		if (c.boss)
		{
			bool flag = false;
			for (int i = 0; i < CharMgr.character.Length; i++)
			{
				if (!CharMgr.character[i].exists || !CharMgr.character[i].boss || i == c.ID)
				{
					continue;
				}
				if (MonsterCatalog.catalog[CharMgr.character[i].monsterIdx].ai != 32)
				{
					flag = true;
				}
				if (!flag)
				{
					continue;
				}
				flag = false;
				_ = CharMgr.character[i];
				int num = -1;
				for (int j = 0; j < MapMgr.map.triggerMgr.arena.Length; j++)
				{
					Arena arena = MapMgr.map.triggerMgr.arena[j];
					if (arena != null)
					{
						for (int k = 0; k < arena.bossCount; k++)
						{
							if (arena.bossMapIdx[k] == c.mapIdx)
							{
								num = j;
								break;
							}
						}
					}
					if (num > -1)
					{
						break;
					}
				}
				if (num <= -1)
				{
					continue;
				}
				int arenaBossCount = MapMgr.map.triggerMgr.GetArenaBossCount(num);
				for (int l = 0; l < arenaBossCount; l++)
				{
					if (MapMgr.map.triggerMgr.GetArenaBossIdx(num, l) == i)
					{
						flag = true;
					}
				}
			}
			if (!flag && (GameStateManager.vanquishedMode != 0 || GameStateManager.vanquishedFrame <= 0f))
			{
				MapMgr.map.triggerMgr.VanquishBoss(c.mapIdx);
				GameStateManager.Vanquish();
			}
			if (GameStateManager.wordsFrame < 0f)
			{
				int layer = CharCols.GetLayer(c.loc);
