	public void UpdateDeath()
	{
		if (!(c.hp <= 0f) || !(c.dyingFrame <= 0f))
		{
			return;
		}
		if (c.state == 0 || c.state == 2)
		{
			c.vox.Die();
			if (c.playerIdx == -1)
			{
				PlayerMgr.AddBeastKill(MonsterCatalog.catalog[c.monsterIdx], c);
			}
			if (c.lastHitBy > -1 && c.lastHitBy < CharMgr.character.Length)
			{
				CharMgr.character[c.lastHitBy].GetPlayer();
			}
			if (PlayerMgr.IsSaltCharacter(c))
			{
				PlayerMgr.RecoverSalt(c);
			}
			Player player = c.GetPlayer();
			if (player != null)
			{
				c.buffs.Reset();
				player.dialog = new PlayerDialog(player);
				player.createSaltStatueFrame = Rand.GetRandomFloat(1.1f, 1.75f);
				GameStateManager.pvpMode = false;
				SteamServiceMgr.IncrementStat(Stats.statName[0], 1);
				if (c.lastHitBy > -1)
				{
					player.playerBeasts.AddKilledBy(CharMgr.character[c.lastHitBy]);
					int arenaIdx = MapMgr.map.triggerMgr.GetArenaIdx(c);
					bool flag = false;
					if (arenaIdx > -1)
					{
						int arenaBossIdx = MapMgr.map.triggerMgr.GetArenaBossIdx(arenaIdx, 0);
						if (arenaBossIdx > -1)
						{
							Character character = CharMgr.character[arenaBossIdx];
							if (character.flag != null)
							{
								WorldValuesMgr.BossLoss(character);
								flag = true;
							}
							if (arenaBossIdx != c.lastHitBy)
							{
								player.playerBeasts.AddKilledBy(CharMgr.character[arenaBossIdx]);
							}
						}
					}
					if (!flag)
					{
						Character character2 = CharMgr.character[c.lastHitBy];
						if (character2.boss && character2.flag != null)
						{
							WorldValuesMgr.BossLoss(character2);
						}
					}
				}
				else if (player.latestBossStr != "")
				{
					player.playerBeasts.AddKilledBy(player.latestBossStr);
				}
			}
			else if (c.boss && c.flag != null && c.lastHitBy > -1)
			{
				WorldValuesMgr.BossWin(c);
			}
			c.rects.MakeSaltBomb();
			if (PlayerMgr.IsSaltCharacter(c))
			{
				c.rects.MakeRealSaltBomb();
			}
			switch (c.anim.animName)
			{
			case "hitland":
				if (c.anim.CheckAnim("hitlanddie") > -1)
				{
					c.anim.SetAnimation("hitlanddie");
				}
				break;
			default:
				c.anim.SetAnimation("die");
				break;
			case "stomped":
			case "gibbed":
			case "slimed":
			case "devouredend":
			case "eatenend":
			case "hitlanddie":
				break;
			}
			c.dyingFrame = 1f;
		}
		else
		{
			switch (c.anim.animName)
			{
			case "jhit":
				return;
			case "jmid":
				return;
			case "jfall":
				return;
			}
			c.anim.SetAnimation("jhit");
		}
	}

