	public void FindRandomSaltTaker(Player p)
	{
		int num = -1;
		float num2 = 0f;
		for (int i = 0; i < CharMgr.maxChars; i++)
		{
			Character character = CharMgr.character[i];
			if (!character.exists || !(character.origVec.X > 0f) || !(character.origVec.Y > 0f) || !(character.hp > 0f) || i == c.ID || HitTeam.GetSameTeam(character, c))
			{
				continue;
			}
			int type = MonsterCatalog.catalog[CharMgr.character[i].monsterIdx].type;
			if (type == 1 || (uint)(type - 8) <= 1u)
			{
				Vector2 vector = character.loc - c.update.lastGroundedLoc;
				if (vector.X < 0f)
				{
					vector.X = 0f - vector.X;
				}
				if (vector.Y < 0f)
				{
					vector.Y = 0f - vector.Y;
				}
				float num3 = vector.X + vector.Y;
				if (num == -1 || num3 < num2)
				{
					num = i;
					num2 = num3;
				}
			}
		}
		if (num > -1)
		{
			SetSaltTaker(p, num);
		}
		else
		{
			p.createSaltStatueFrame = -1f;
