	public void TryDropOnDeath(int lastHitBy)
	{
		List<string> list = null;
		DropGold();
		if (c.arrowHitCount > 0 || c.boltHitCount > 0)
		{
			list = new List<string>();
			if (c.arrowHitCount > 0)
			{
				list.Add("arrow/" + (c.arrowHitCount / 2 + 1));
			}
			if (c.boltHitCount > 0)
			{
				list.Add("bolt/" + (c.boltHitCount / 2 + 1));
			}
		}
		if (lastHitBy > -1)
		{
			Character character = ((lastHitBy > -1) ? CharMgr.character[lastHitBy] : null);
			MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
			for (int i = 0; i < 6; i++)
			{
				if (monsterDef.monsterDrop[i].dropLoot != "" && character != null && character.stats.GetDropSuccess(monsterDef.monsterDrop[i].dropRate))
				{
					if (character.playerIdx > -1)
					{
						character.GetPlayer().playerBeasts.AddDrop(monsterDef, i);
					}
					if (list == null)
					{
						list = new List<string>();
					}
					list.Add(monsterDef.monsterDrop[i].dropLoot + ((monsterDef.monsterDrop[i].dropCount > 1) ? ("/" + monsterDef.monsterDrop[i].dropCount) : ""));
				}
			}
		}
		if (list == null)
		{
			if (c.drops != null && !c.boss)
			{
				MapMgr.pickupMgr.Drop(c.drops, c.loc + new Vector2(0f, -50f), c.flag);
			}
			return;
		}
		if (c.drops != null)
		{
			string[] drops = c.drops;
			foreach (string item in drops)
			{
				list.Add(item);
			}
		}
		if (!c.boss)
		{
			MapMgr.pickupMgr.Drop(list.ToArray(), c.loc + new Vector2(0f, -50f), c.flag);
		}
	}

	private void DropGold()
	{
		if (c.playerIdx >= 0)
		{
			return;
		}
		float num = 1f;
		if (c.lastHitBy > -1)
		{
			Character character = CharMgr.character[c.lastHitBy];
			if (character.stats.GetRingFlag(9))
			{
				num = 1.1f;
			}
			if (character.playerIdx > -1 && character.equipment.active && character.equipment.loadout[character.equipment.loadoutIdx, 0].catalogIdx > -1 && character.equipment.loadout[character.equipment.loado
			{
				num *= 1.25f;
			}
			if (character.buffs.GetGoldenBuff())
			{
				num *= 2f;
			}
			if (character.playerIdx > -1 && PlayerMgr.GetMainPlayer().sanctuaryBonus[2])
			{
				num *= 1.1f;
			}
		}
		int num2 = (int)((float)MonsterCatalog.catalog[c.monsterIdx].salt * num);
		if (PlayerMgr.GetMainPlayer() != null && PlayerMgr.GetMainPlayer().IsScaledRandomizer())
		{
			num2 = (int)(RandomizerMgr.GetTierAdjustSalt(c) * num);
		}
		if (num2 <= 0)
		{
			num2 *= -1;
		}
		if (!c.boss)
		{
			num2 = Rand.GetRandomInt(0, num2);
		}
		if (GameModeMgr.IsGameEnhanced() && GameStateManager.playthroughCount > 0)
		{
			num2 += 10 + 10 * GameStateManager.playthroughCount;
			if (c.boss)
			{
				num2 += 500 + 100 * GameStateManager.playthroughCount;
			}
			num2 = (int)((float)num2 * 1.1f * (float)GameStateManager.playthroughCount);
		}
		int num3 = Rand.GetRandomInt(0, 4);
		if (c.boss)
		{
			num3 = 10;
		}
		for (int i = 0; i < num3; i++)
		{
			ParticleManager.AddAdditiveParticle(112, c.loc + Rand.GetRandomVec2(-40f, 40f, -50f, -40f), default, c.boss ? Rand.GetRandomFloat(0f, 5f) : Rand.GetRandomFloat(0f, 1f), 0f, num2 / num3 + 1, -1);
		}
	}
