	public float GetMaxPoise()
	{
		float num = 0f;
		if (c.playerIdx > -1)
		{
			if (c.equipment.active)
			{
				if (c.equipment.helm.catalogIdx > -1 && c.equipment.helm.catalogIdx < LootCatalog.category[2].loot.Length)
				{
					num += LootCatalog.category[2].loot[c.equipment.helm.catalogIdx].values[7];
				}
				if (c.equipment.armor.catalogIdx > -1 && c.equipment.armor.catalogIdx < LootCatalog.category[2].loot.Length)
				{
					num += LootCatalog.category[2].loot[c.equipment.armor.catalogIdx].values[7];
				}
				if (c.equipment.gloves.catalogIdx > -1 && c.equipment.gloves.catalogIdx < LootCatalog.category[2].loot.Length)
				{
					num += LootCatalog.category[2].loot[c.equipment.gloves.catalogIdx].values[7];
				}
				if (c.equipment.boots.catalogIdx > -1 && c.equipment.boots.catalogIdx < LootCatalog.category[2].loot.Length)
				{
					num += LootCatalog.category[2].loot[c.equipment.boots.catalogIdx].values[7];
				}
				if (GetRingFlag(13))
				{
					num += 20f;
				}
			}
			num *= 0.5f;
			if (c.buffs.GetWillBuff() > 0f && GameModeMgr.IsGameEnhanced())
			{
				num *= 1.5f;
			}
			return num;
		}
		MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
		if (GameStateManager.coopPlayerIdx > -1)
		{
			return monsterDef.poise * 1.5f;
		}
		return monsterDef.poise;
	}

	public float GetSanctuaryMaxSP()
