	public float GetCastMin()
	{
		float sanctuaryMaxSP = GetSanctuaryMaxSP();
		if (c.stats.GetRingFlag(11) && c.stats.GetRingFlag(20))
		{
			return 0f;
		}
		float num = 2f;
		if (c.stats.GetRingFlag(11))
		{
			num = 3f;
		}
		else if (c.stats.GetRingFlag(20))
		{
			num = 4f;
		}
		return sanctuaryMaxSP / num;
	}

	public bool GetCanCast()
	{
		return c.stats.GetSanctuaryMaxSP() - c.spCapDmg > GetCastMin();
	}

